-- Generated by Murakumo: load tpch_erp.supplier (append), without Murakumo. Run it from the project folder.

-- The files under landing/tpch_erp/supplier/ that were not loaded before.
create or replace temp table new_rows as
select cast(s_suppkey as BIGINT) as s_suppkey, cast(s_name as VARCHAR) as s_name, cast(s_address as VARCHAR) as s_address, cast(s_nationkey as INTEGER) as s_nationkey, cast(s_phone as VARCHAR) as s_phone, cast(s_acctbal as DECIMAL(15,2)) as s_acctbal, cast(s_comment as VARCHAR) as s_comment, filename
from read_json('landing/tpch_erp/supplier/supplier_*.jsonl', format = 'newline_delimited', filename = true, columns = {'s_suppkey': 'BIGINT', 's_name': 'VARCHAR', 's_address': 'VARCHAR', 's_nationkey': 'INTEGER', 's_phone': 'VARCHAR', 's_acctbal': 'DECIMAL(15,2)', 's_comment': 'VARCHAR'})
where parse_filename(filename) not in (select parse_filename(path) from audit.loaded_files where table_name = 'supplier');
-- Append: the new files' rows are added.
insert into raw_tpch_erp.supplier (s_suppkey, s_name, s_address, s_nationkey, s_phone, s_acctbal, s_comment, _ingested_at, _batch_id)
select s_suppkey, s_name, s_address, s_nationkey, s_phone, s_acctbal, s_comment, now(), parse_filename(filename) from new_rows;
-- Remember the files, so the next run skips them.
insert into audit.loaded_files (table_name, path, size, sha256, rows_ingested, batch_id, loaded_at)
select 'supplier', filename, null, null, count(*), parse_filename(filename), now()
from new_rows group by filename;
drop table new_rows;
